use super::{Mapping, compiler};
use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::PathBuf;

pub(super) fn outputs(rows: &[Mapping], bitcode_hash: &str) -> BTreeMap<PathBuf, String> {
    let mut rust = String::from(
        "/*\n * SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.\n * SPDX-License-Identifier: Apache-2.0\n */\n\n// @generated by cuda-intrinsics-gen from overlay/libdevice_math.toml. DO NOT EDIT.\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct MathMapping {\n    pub libm: Option<&'static str>,\n    pub width: &'static str,\n    pub variant: Option<&'static str>,\n    pub constant: Option<&'static str>,\n    pub paths: &'static [&'static str],\n    pub signature: &'static str,\n    pub placeholders: &'static [&'static str],\n    pub cmath: Option<&'static str>,\n    pub libdevice: Option<&'static str>,\n    pub llvm: Option<&'static str>,\n    pub lowering: Option<&'static str>,\n    pub link: &'static str,\n}\n\npub const MAPPINGS: &[MathMapping] = &[\n",
    );
    let exports = rows.iter().filter(|row| row.libm.is_some()).count();
    let mut reference = format!(
        "<!-- SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved. -->\n<!-- SPDX-License-Identifier: Apache-2.0 -->\n<!-- @generated by cuda-intrinsics-gen. DO NOT EDIT. -->\n\n# Compiler math mappings\n\n{exports} mapped f32/f64 libm exports, plus core-only compiler routes.\n\nThe same shard generates compiler dispatch, placeholder constants, symbol lookup,\noperand counts, cmath interception, and libdevice link requirements. Handwritten\nsemantic expansions remain responsible for sincos, frexp, min/max, and fast binops.\n\nLibdevice bitcode SHA-256: `{bitcode_hash}`.\n\n`libnvvm` links only on that backend; `always` links on both; `never` uses\na handwritten expansion. Aliases are separate exports sharing a mapping.\n\n| libm export | Rust signature | libdevice symbol | LLVM NVPTX alternative | Handwritten lowering | Linking |\n| --- | --- | --- | --- | --- | --- |\n"
    );
    for row in rows {
        writeln!(rust, "MathMapping {{ libm: {:?}, width: {:?}, variant: {:?}, constant: {:?}, paths: &{:?}, signature: {:?}, placeholders: &{:?}, cmath: {:?}, libdevice: {:?}, llvm: {:?}, lowering: {:?}, link: {:?} }},", row.libm, row.width, row.variant, row.constant, row.paths, row.signature, row.placeholders, row.cmath, row.libdevice, row.llvm, row.lowering, row.link.as_str()).unwrap();
        writeln!(
            reference,
            "| {} | `{}` | {} | {} | {} | `{}` |",
            code(row.libm.as_deref()),
            row.signature,
            code(row.libdevice.as_deref()),
            code(row.llvm.as_deref()),
            code(row.lowering.as_deref()),
            row.link.as_str()
        )
        .unwrap();
    }
    rust.push_str("];\n");
    BTreeMap::from([
        (
            PathBuf::from("intrinsics/generated/libdevice_math.rs"),
            rust,
        ),
        (PathBuf::from("intrinsics/libdevice-math.md"), reference),
        (
            PathBuf::from("crates/dialect-mir/src/generated/libdevice_math.rs"),
            compiler::render(rows),
        ),
    ])
}

fn code(value: Option<&str>) -> String {
    value
        .map(|text| format!("`{text}`"))
        .unwrap_or_else(|| " ".into())
}
